            aOrbiterJ = (((aWandererG + RotL64(aIngress, 19U)) + 0x9392225823EE2CF0ULL) + aOASaltF[(((511U - aIndex) + 346U)) & S_SALT1]) + aNonceWordA;
            aOrbiterH = (((aWandererB + RotL64(aScatter, 5U)) + 0x91CADE9048B279AFULL) + aOASaltA[((aIndex + 187U)) & S_SALT1]) + aNonceWordI;
