            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xF6BAA4938E6760D2ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xA4C6EA0205EE6941ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0FECEC78A9B782EBULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xA8C059FC52B758C3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xDCFE9F3F31E365E3ULL;
