            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xC0AC4B9E7B5A21F5ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x85D4489147424F2FULL;
