            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x6F07C7D42066912CULL) + aNonceWordC;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0xAD5B9AD488725A0DULL) ^ aOUSaltC[(((511U - aIndex) + 354U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x98991CBA67069D4DULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x176BD1CE4F51488DULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0xA27A86EE10934F23ULL) ^ aOUSaltB[(((511U - aIndex) + 433U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x78D06F5C594A8A31ULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xB60ECBC055EA89D4ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x21B0885037938810ULL;
