            //
            aWandererC = aWandererC + ((((RotL64(aScatter, 57U) + aOrbiterA) + RotL64(aOrbiterI, 41U)) + RotL64(aCarry, 5U)) + aNonceWordJ);
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 34U) + aOrbiterC) + RotL64(aOrbiterB, 37U)) + aWUSaltC[((aIndex + 364U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 41U) + aOrbiterJ) + RotL64(aOrbiterA, 48U)) + aNonceWordM);
