            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterB, 29U)) + aOrbiterH);
            aWandererH = aWandererH + ((RotL64(aScatter, 53U) + aOrbiterH) + RotL64(aOrbiterK, 5U));
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 14U) + aOrbiterG) + RotL64(aOrbiterF, 44U)) + aWUSaltB[((aIndex + 391U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aCross, 23U) + aOrbiterE) + RotL64(aOrbiterC, 57U)) + aNonceWordK) + aWUSaltG[((aIndex + 376U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererF, 6U));
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererK, 11U));
            aCarry = aCarry + (RotL64(aWandererH, 57U) ^ aWandererG);
            aCarry = aCarry + (RotL64(aWandererE, 39U) ^ aWandererC);
            aCarry = aCarry + (RotL64(aWandererB, 3U) ^ aWandererD);
            aCarry = aCarry + RotL64(aWandererA, 19U);
            aCarry = aCarry + RotL64(aIngress, 51U);
            aCarry = TwistMix64::DiffuseB(aCarry);
            //
