            aPrevious = aIngress;
            //
            aIngress = RotL64(aFireLaneA[((aIndex + 7664U)) & S_BLOCK1], 24U) ^ RotL64(aSource[((aIndex + 5499U)) & S_BLOCK1], 47U);
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aDomainWordIngress) ^ aNonceWordH));
            //
            aCross = RotL64(aSource[((S_BLOCK1 - aIndex + 9159U)) & S_BLOCK1], 10U) ^ RotL64(aNonceLane[((S_BLOCK1 - aIndex + 7109U)) & S_BLOCK1], 23U);
            aCross = TwistMix64::DiffuseC(((aCross ^ aDomainWordCross) ^ aNonceWordD));
            //
            aScatter = (RotL64(aIngress, 51U) + RotL64(aCarry, 19U)) ^ (RotL64(aPrevious, 6U) ^ RotL64(aCross, 37U));
            aScatter = TwistMix64::DiffuseA(((aScatter ^ aDomainWordScatter) ^ aNonceWordE));
            //
            aOrbiterG = (((aWandererI + RotL64(aScatter, 19U)) + RotL64(aCarry, 35U)) + 0xEA04366384A8C642ULL) + aOASaltE[(((511U - aIndex) + 136U)) & S_SALT1];
            aOrbiterH = (((aWandererC + RotL64(aPrevious, 39U)) + 0x0D53828E74C55EFEULL) + aOASaltC[((aIndex + 433U)) & S_SALT1]) + aNonceWordP;
            aOrbiterF = ((aWandererK + RotL64(aCross, 30U)) + 0x975E1081C432F1FAULL) + aOASaltH[(((511U - aIndex) + 212U)) & S_SALT1];
            aOrbiterI = ((aWandererB + RotL64(aIngress, 57U)) + RotL64(aCarry, 29U)) + 0x8E7964480834A3DFULL;
            aOrbiterJ = (aWandererH + RotL64(aScatter, 35U)) + 0x9950F9A644DF57EAULL;
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 43U)) + 0x78FA791E58B84986ULL) + aNonceWordM;
            aOrbiterC = (aWandererG + RotL64(aCross, 51U)) + 0xE363B644A7CBAEFCULL;
            aOrbiterK = (((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 23U)) + 0xFAA56EBCE4D59C84ULL) + aNonceWordN;
            aOrbiterA = ((aWandererE + RotL64(aScatter, 24U)) + 0x2FB782843EAF7D74ULL) + aOASaltD[(((511U - aIndex) + 51U)) & S_SALT1];
            aOrbiterB = (aWandererD + RotL64(aPrevious, 41U)) + 0x362E0CDBCA6E9FC1ULL;
            aOrbiterE = (((aWandererJ + RotL64(aCross, 47U)) + 0x5A7484153B45C737ULL) + aOASaltB[((aIndex + 503U)) & S_SALT1]) + aNonceWordB;
