            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x71794AEE698F49E5ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x85AD34165536F47BULL;
            aOrbiterD = RotL64((aOrbiterD * 0x34C540A10531A347ULL), 51U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x0A934A063F3DC211ULL) + aOUSaltB[((aIndex + 30U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x77E216FA8F93E170ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x819EF0DCF3ED1DEBULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xD2D666AAE184E650ULL;
            aOrbiterB = (((aOrbiterB ^ aOrbiterJ) ^ 0x228B35A7F3EB892AULL) ^ aOUSaltG[((aIndex + 256U)) & S_SALT1]) ^ aNonceWordA;
            aOrbiterB = RotL64((aOrbiterB * 0x680E99EA85151A55ULL), 43U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xE87C5EAEC17E53B0ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xA1D528796868DB39ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xC8F13DE0F67DD9DDULL), 35U);
            //
            aOrbiterD = (((aOrbiterD + aOrbiterB) + 0x0C5909A982B6D3B8ULL) + aOUSaltA[((aIndex + 37U)) & S_SALT1]) + aNonceWordC;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x61265B932A304A6DULL) ^ aOUSaltE[((aIndex + 143U)) & S_SALT1];
