            aIngress = aIngress + RotL64(aOrbiterF, 47U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterB, 29U)) + aOrbiterA) + aNonceWordP);
            aWandererC = aWandererC + ((RotL64(aPrevious, 5U) + RotL64(aOrbiterJ, 40U)) + aOrbiterB);
            aWandererA = aWandererA ^ ((((RotL64(aCross, 24U) + aOrbiterA) + RotL64(aOrbiterD, 19U)) + aNonceWordO) + aWUSaltD[((aIndex + 254U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 41U) + aOrbiterD) + RotL64(aOrbiterI, 11U)) + RotL64(aCarry, 35U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 43U) + RotL64(aOrbiterF, 51U)) + aOrbiterH);
            aWandererI = aWandererI + ((RotL64(aPrevious, 47U) + RotL64(aOrbiterE, 57U)) + aOrbiterG);
            aWandererK = aWandererK ^ (((RotL64(aCross, 27U) + aOrbiterK) + RotL64(aOrbiterE, 3U)) + aWUSaltB[(((511U - aIndex) + 411U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aIngress, 3U) + aOrbiterI) + RotL64(aOrbiterK, 53U));
            aWandererG = aWandererG ^ (((RotL64(aScatter, 13U) + RotL64(aOrbiterH, 26U)) + aOrbiterC) + aWUSaltE[(((511U - aIndex) + 278U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aPrevious, 51U) + RotL64(aOrbiterG, 35U)) + aOrbiterF) + RotL64(aCarry, 23U));
            aWandererH = aWandererH ^ (((RotL64(aCross, 18U) + aOrbiterC) + RotL64(aOrbiterJ, 21U)) + aWUSaltH[((aIndex + 119U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererJ, 43U));
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererC, 3U));
            aCarry = aCarry + (RotL64(aWandererG, 58U) ^ aWandererI);
