    const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xFDB1FE121BF43577ULL + 0x8C0BFB6E84AB9A3DULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xA15864AA971FBEC5ULL + 0xD3956B0A9F485B8BULL);
