            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x2B2EC7564D573567ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x4D11445DF275BE5EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x73757045D5126BB5ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xF1BC5F92068C6709ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x958EB9F2DE2D5AA3ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x7D96F52DF867214BULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x1A4B9CF9F7DB9F15ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x9A0E8D0BBB730EDBULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9E54E40E2E772EBDULL), 27U);
            //
            aOrbiterK = (((aOrbiterK + aOrbiterE) + 0xA7A87027D2A4D82EULL) + aOUSaltB[(((511U - aIndex) + 339U)) & S_SALT1]) + aNonceWordH;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x73BC67C2A6C9ADCDULL;
            aOrbiterH = RotL64((aOrbiterH * 0xCDF378B88B34D9EDULL), 39U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x676F0E2A1222CD5BULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x786F65F8AD59BD64ULL;
