            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x50A285DE663E276AULL) + aOUSaltH[(((511U - aIndex) + 65U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x9AD966E19EEA3CE6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEFD98747DA7987C7ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x8BF6E82931E139BDULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0x3D276959765AD598ULL) ^ aOUSaltC[(((511U - aIndex) + 240U)) & S_SALT1];
