            aCross = (RotL64(aCrystalLaneD[((S_BLOCK1 - aIndex + 11645U)) & S_BLOCK1], 35U) ^ RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 9288U)) & S_BLOCK1], 5U));
            aCross ^= RotL64(aSpiritLaneD[((S_BLOCK1 - aIndex + 11101U)) & S_BLOCK1], 47U);
