            aScatter = (RotL64(aCross, 5U) ^ RotL64(aIngress, 20U)) + (RotL64(aPrevious, 57U) + RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseC(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordL));
            //
            aOrbiterG = ((aWandererE + RotL64(aScatter, 53U)) + 0xD6073655BAA7830CULL) + aNonceWordP;
            aOrbiterE = ((aWandererB + RotL64(aPrevious, 43U)) + 0x6C72AA95BEB1655CULL) + aOASaltG[(((511U - aIndex) + 15U)) & S_SALT1];
