            //
            aIngress = (RotL64(aKineticLaneC[((aIndex + 28350U)) & S_BLOCK1], 37U) ^ RotL64(aKineticLaneA[((aIndex + 30614U)) & S_BLOCK1], 27U));
            aIngress ^= RotL64(aVaporLaneA[((aIndex + 28740U)) & S_BLOCK1], 5U);
