            aOrbiterJ = (((aWandererA + RotL64(aCross, 53U)) + 0x47CBB154D01C70C7ULL) + aOASaltE[((aIndex + 335U)) & S_SALT1]) + aNonceWordD;
            aOrbiterK = (((aWandererE + RotL64(aIngress, 57U)) + RotL64(aCarry, 53U)) + 0xEBD1CD4302ADF0C8ULL) + aOASaltH[((aIndex + 258U)) & S_SALT1];
            aOrbiterH = (aWandererC + RotL64(aScatter, 36U)) + 0xAE67EF52435A8B48ULL;
