            aOrbiterF = (((aWandererD + RotL64(aCross, 29U)) + RotL64(aCarry, 47U)) + 0x1D56B533BC9676B9ULL) + aOASaltC[((aIndex + 169U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aIngress, 11U)) + 0x1E90AB8B10F90F65ULL;
