            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x8DACED56F67C8D43ULL) + aOUSaltA[(((511U - aIndex) + 137U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x464A43F8F6AC6276ULL;
