            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0xC3CE826D9655E256ULL) + aOUSaltH[(((511U - aIndex) + 36U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x1A31A640B2B03569ULL;
