            aOrbiterG = RotL64((aOrbiterG * 0x1BF7F37B70A489A3ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x852B78BD35B7AFA2ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x375C44270665B10CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1DA7C6976EB64F13ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xE8EB9BB2627A2D67ULL;
