            aWandererI = aWandererI ^ (((RotL64(aScatter, 40U) + RotL64(aOrbiterE, 37U)) + aOrbiterH) + aWUSaltH[(((511U - aIndex) + 149U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterH, 19U)) + aOrbiterC) + aWUSaltF[(((511U - aIndex) + 251U)) & S_SALT1]);
