            aWandererA = aWandererA + (((RotL64(aIngress, 11U) + aOrbiterG) + RotL64(aOrbiterK, 29U)) + RotL64(aCarry, 21U));
            aWandererB = aWandererB ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterK, 53U)) + aOrbiterA);
            aWandererH = aWandererH + (((RotL64(aPrevious, 5U) + RotL64(aOrbiterF, 21U)) + aOrbiterI) + aWUSaltE[((aIndex + 259U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((((RotL64(aCross, 23U) + aOrbiterD) + RotL64(aOrbiterB, 42U)) + aNonceWordH) + aWUSaltD[((aIndex + 51U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererD, 27U));
