        //      aIceLaneD (-->), aIceLaneB (-->), aSource (-->), aSoilLaneC (<-?->)
        //
        // Cross:
        //      aIceLaneC (<--), aIceLaneA (<--), aSoilLaneB (<--), aWaterLaneB (<-?->)
        //
