            aPrevious = aIngress;
            //
            aIngress = (RotL64(aWaterLaneD[((aIndex + 3819U)) & S_BLOCK1], 21U) ^ RotL64(aWaterLaneB[((aIndex + 5992U)) & S_BLOCK1], 57U));
