            aScatter = (RotL64(aIngress, 3U) ^ RotL64(aCross, 19U)) ^ (RotL64(aPrevious, 35U) + RotL64(aCarry, 50U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = (aWandererK + RotL64(aScatter, 43U)) + 0x42914233B29DA0DEULL;
            aOrbiterJ = ((aWandererG + RotL64(aPrevious, 29U)) + 0xC5D207603FB49DDCULL) + aOASaltA[((aIndex + 501U)) & S_SALT1];
            aOrbiterG = ((aWandererB + RotL64(aCross, 60U)) + RotL64(aCarry, 27U)) + 0x70C33A1B734BE9FDULL;
            aOrbiterC = ((aWandererC + RotL64(aIngress, 19U)) + 0xB9E208B4E75AA3DFULL) + aOASaltD[((aIndex + 243U)) & S_SALT1];
