            aCarry = aCarry + (RotL64(aWandererH, 26U) ^ aWandererJ);
            aCarry = aCarry + (RotL64(aWandererE, 13U) ^ aWandererC);
            aCarry = aCarry + (RotL64(aWandererB, 53U) ^ aWandererK);
