            aWandererH = aWandererH + ((RotL64(aPrevious, 29U) + RotL64(aOrbiterG, 43U)) + aOrbiterC);
            aWandererI = aWandererI ^ ((RotL64(aCross, 57U) + aOrbiterH) + RotL64(aOrbiterD, 19U));
