            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x1A2871A542C78772ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0xB9E6A791E5E6D50CULL) ^ aOUSaltD[(((511U - aIndex) + 258U)) & S_SALT1];
