            aOrbiterJ = RotL64((aOrbiterJ * 0x4D2CFDC6B73F05FDULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x5916936C19E90531ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x9B616D8FE56F93D5ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x44E3D77E6203A86DULL), 5U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x3F6B516B83F24CA6ULL) + aOUSaltB[((aIndex + 465U)) & S_SALT1];
