            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 52U) ^ RotL64(aIngress, 11U)) + (RotL64(aPrevious, 37U) ^ RotL64(aCross, 23U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererB + RotL64(aIngress, 19U)) + 0xBD772F7574644EA5ULL;
            aOrbiterJ = ((aWandererA + RotL64(aScatter, 35U)) + RotL64(aCarry, 5U)) + 0xAF114FCD32476872ULL;
            aOrbiterH = ((aWandererC + RotL64(aPrevious, 22U)) + 0xAB514DC9D4592B14ULL) + aOASaltG[(((511U - aIndex) + 339U)) & S_SALT1];
            aOrbiterD = ((aWandererK + RotL64(aCross, 47U)) + 0x8CC3DA159FAE9E76ULL) + aOASaltE[(((511U - aIndex) + 379U)) & S_SALT1];
            aOrbiterG = ((aWandererI + RotL64(aIngress, 27U)) + RotL64(aCarry, 37U)) + 0x0EBEDE26893E5DF4ULL;
            aOrbiterB = (aWandererE + RotL64(aScatter, 51U)) + 0xBCC7D9C0A265BBB6ULL;
            aOrbiterF = (aWandererH + RotL64(aPrevious, 58U)) + 0x1B125BF0C80B5C36ULL;
            aOrbiterA = (aWandererJ + RotL64(aCross, 37U)) + 0x1043870B5EA8D0EAULL;
            aOrbiterE = (((aWandererG + RotL64(aIngress, 41U)) + RotL64(aCarry, 27U)) + 0x7F0ED3A5E0B42EF4ULL) + aOASaltA[(((511U - aIndex) + 283U)) & S_SALT1];
            aOrbiterI = ((aWandererF + RotL64(aScatter, 11U)) + 0x6E9C2436CA7ADAA9ULL) + aOASaltH[((aIndex + 86U)) & S_SALT1];
            aOrbiterK = (aWandererD + RotL64(aPrevious, 43U)) + 0x5AA7EC4527BF7E21ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x99CCE3609266E1A1ULL) + aOUSaltA[((aIndex + 467U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x9345D8F8DB46F729ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7DC70D55CDF5AF23ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x7204451E14B04777ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xEAC6E4DE9241DC87ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9EF3071082C91025ULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x6D5570E27D1A8F6BULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xC09DB204F5A513C9ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x933D38A9ED7C44F1ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x95EC1DC2CFBAE6B5ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xC39BC59C71D34A76ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x1D8C90640FA72103ULL), 43U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xD7674B9FC5931559ULL) + aOUSaltH[((aIndex + 262U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x1F89F64F97CA8593ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1050C48F7101C519ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x58895FD9221959A7ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x7DD3C250D8CC8E37ULL) ^ aOUSaltC[((aIndex + 201U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x2F5B183867408DADULL), 41U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0x1B4D64B9493019EFULL) + aOUSaltG[((aIndex + 351U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x027140863E12760FULL;
            aOrbiterG = RotL64((aOrbiterG * 0xD0847E5E77A03731ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x60F3969E91E0BD34ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0xC0E72A6C96C797DEULL) ^ aOUSaltD[(((511U - aIndex) + 172U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x66D0236C517C734BULL), 13U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x57F668A41DD3CF09ULL) + aOUSaltE[((aIndex + 227U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x998C6A8AAE4914B8ULL;
