            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 15309U)) & S_BLOCK1], 50U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 14818U)) & S_BLOCK1], 27U));
            aCross ^= (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 15979U)) & S_BLOCK1], 11U) ^ RotL64(aWoodLaneC[((aIndex + 14859U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 35U) + RotL64(aCarry, 5U)) ^ (RotL64(aIngress, 23U) + RotL64(aCross, 54U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererI + RotL64(aScatter, 51U)) + 0xC2897BD58CB39CB9ULL) + aOASaltG[((aIndex + 317U)) & S_SALT1];
            aOrbiterG = ((aWandererG + RotL64(aPrevious, 27U)) + 0x772AD7B9A661869BULL) + aOASaltE[(((511U - aIndex) + 310U)) & S_SALT1];
            aOrbiterK = ((aWandererC + RotL64(aCross, 35U)) + RotL64(aCarry, 57U)) + 0x8D0EDDE7E69B5DE6ULL;
            aOrbiterF = (aWandererJ + RotL64(aIngress, 5U)) + 0xD61D2E73238327C6ULL;
            aOrbiterI = (aWandererA + RotL64(aScatter, 53U)) + 0xD6A0A0AE256A1C7EULL;
            aOrbiterB = ((aWandererH + RotL64(aPrevious, 23U)) + RotL64(aCarry, 41U)) + 0x822CA628615A156DULL;
            aOrbiterJ = (aWandererK + RotL64(aCross, 48U)) + 0x6AC1941C72A2F052ULL;
            aOrbiterD = (aWandererF + RotL64(aIngress, 21U)) + 0x8E02C901EA514371ULL;
