            aWandererF = aWandererF + (((RotL64(aIngress, 57U) + RotL64(aOrbiterE, 39U)) + aOrbiterF) + aWUSaltB[(((511U - aIndex) + 1U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((((RotL64(aScatter, 10U) + aOrbiterC) + RotL64(aOrbiterK, 48U)) + RotL64(aCarry, 13U)) + aWUSaltE[((aIndex + 339U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererD, 53U) ^ aWandererE);
