            //
            aPrevious = aIngress;
            //
            aIngress = (RotL64(aVaporLaneA[((aIndex + 5298U)) & S_BLOCK1], 42U) ^ RotL64(aVaporLaneB[((aIndex + 5189U)) & S_BLOCK1], 51U));
