            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x4EFBF47EAA2FD9F3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x3D958DA62D17CA4DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0DA48A99C65810EDULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x98D7BC35A67B67BBULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x80B51C725721CE60ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA648306D27CA63E3ULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x49D7C91ED31491B4ULL;
