            aWandererC = aWandererC + (((RotL64(aIngress, 43U) + aOrbiterI) + RotL64(aOrbiterH, 6U)) + aWUSaltH[(((511U - aIndex) + 464U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aScatter, 23U) + aOrbiterK) + RotL64(aOrbiterE, 19U));
