            aCross = (RotL64(aVaporLaneA[((S_BLOCK1 - aIndex + 10020U)) & S_BLOCK1], 51U) ^ RotL64(aVaporLaneB[((S_BLOCK1 - aIndex + 10709U)) & S_BLOCK1], 18U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 8951U)) & W_KEY1], 5U) ^ RotL64(aShadowLaneD[((aIndex + 15906U)) & S_BLOCK1], 43U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 40U) ^ RotL64(aCarry, 57U)) + (RotL64(aCross, 5U) + RotL64(aPrevious, 21U));
