            aWandererG = aWandererG + ((RotL64(aIngress, 46U) + aOrbiterB) + RotL64(aOrbiterG, 3U));
            aWandererK = aWandererK ^ ((RotL64(aScatter, 53U) + RotL64(aOrbiterF, 43U)) + aOrbiterB);
            aWandererC = aWandererC + (((RotL64(aPrevious, 21U) + RotL64(aOrbiterA, 23U)) + aOrbiterJ) + aWUSaltB[(((511U - aIndex) + 417U)) & S_SALT1]);
