            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x8666F02A1E04A642ULL) + aOUSaltG[(((511U - aIndex) + 487U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xCF6B30C7267E3D40ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xF2354A222C1A0AF5ULL), 43U);
