            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x1F40D945D6CB655EULL) + aOUSaltH[(((511U - aIndex) + 68U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x75682D7655EB0C53ULL;
