            //
            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0x050A441FBC863E3BULL) + aOUSaltC[((aIndex + 72U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x84C0D5746EE87E86ULL) ^ aOUSaltE[((aIndex + 391U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x026CCC4176F46FADULL), 27U);
