            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x74907A2F34E05A87ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0xF15586D9C18E579CULL) ^ aOUSaltD[(((511U - aIndex) + 447U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x90CCDAEA71C82B0FULL), 37U);
