            aWandererE = aWandererE ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterF, 14U)) + aOrbiterA);
            //
            aCarry = aCarry + (RotL64(aWandererJ, 60U) ^ aWandererF);
