            aWandererC = aWandererC + ((RotL64(aScatter, 22U) + aOrbiterD) + RotL64(aOrbiterH, 5U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterA, 35U)) + aOrbiterE);
            aWandererF = aWandererF + ((((RotL64(aCross, 43U) + aOrbiterE) + RotL64(aOrbiterI, 53U)) + RotL64(aCarry, 47U)) + aWUSaltE[((aIndex + 414U)) & S_SALT1]);
