            aWandererK = aWandererK ^ ((((RotL64(aIngress, 35U) + RotL64(aOrbiterK, 47U)) + aOrbiterD) + RotL64(aCarry, 43U)) + aWUSaltB[((aIndex + 102U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aScatter, 48U) + aOrbiterH) + RotL64(aOrbiterJ, 3U));
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 53U) + RotL64(aOrbiterI, 37U)) + aOrbiterF) + aWUSaltD[(((511U - aIndex) + 297U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aCross, 19U) + aOrbiterG) + RotL64(aOrbiterK, 18U));
