            aIngress = (RotL64(aWindLaneC[((aIndex + 32177U)) & S_BLOCK1], 6U) ^ RotL64(aWindLaneA[((aIndex + 31740U)) & S_BLOCK1], 23U));
            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 25272U)) & S_BLOCK1], 43U) ^ RotL64(aKineticLaneD[((aIndex + 29255U)) & S_BLOCK1], 35U));
