            aOrbiterD = (aWandererI + RotL64(aPrevious, 41U)) + 0xD2DF70CBD3E78D64ULL;
            aOrbiterF = ((aWandererG + RotL64(aCross, 47U)) + 0x1A38C42A10D7BB67ULL) + aOASaltE[(((511U - aIndex) + 475U)) & S_SALT1];
            aOrbiterK = (aWandererK + RotL64(aIngress, 34U)) + 0x43568771C216EA5FULL;
            aOrbiterG = (((aWandererE + RotL64(aScatter, 3U)) + RotL64(aCarry, 19U)) + 0xE097C078873457C5ULL) + aOASaltC[((aIndex + 378U)) & S_SALT1];
            aOrbiterC = (aWandererD + RotL64(aPrevious, 21U)) + 0x247E0D5A837A6FE7ULL;
            aOrbiterI = ((aWandererJ + RotL64(aCross, 11U)) + 0x6D5D286EDD5CCCE5ULL) + aOASaltF[((aIndex + 167U)) & S_SALT1];
            aOrbiterA = (((aWandererH + RotL64(aIngress, 5U)) + RotL64(aCarry, 5U)) + 0x3D624274F4B4C3C7ULL) + aOASaltG[(((511U - aIndex) + 217U)) & S_SALT1];
            aOrbiterH = (aWandererF + RotL64(aScatter, 19U)) + 0x51D4DE1A733E631AULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x2B5AB638CA2DF1D5ULL;
