            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0x22A991F2D8C20A74ULL) + aOUSaltD[((aIndex + 277U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xB3BA7364FED0F19CULL;
            aOrbiterK = RotL64((aOrbiterK * 0x33CCF33E2B536283ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x81ADDB6542C4E2A7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x793DD73327384A9AULL;
            aOrbiterI = RotL64((aOrbiterI * 0x0194ADF66BBF39D7ULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x52B1216F83538530ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xCA911765F850E962ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xA959F961CF47D9A5ULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x219FCD914D847839ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x118368CA6A04445FULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF727AA8A1BB82705ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xA8567CDB31EC4BBCULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x50366FCD12A22D5AULL;
            aOrbiterE = RotL64((aOrbiterE * 0x63581437DF4D8C25ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x195D24D95D799831ULL;
