            aOrbiterA = RotL64((aOrbiterA * 0x5E7ACEAA839150F1ULL), 39U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x5FCE67CC96411C5CULL) + aOUSaltH[(((511U - aIndex) + 133U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x5E2D19FBE0290495ULL) ^ aOUSaltG[(((511U - aIndex) + 424U)) & S_SALT1];
